\coordinate (T) at (0,2.2);
\coordinate (L) at (-1.2,2.2);
\coordinate (R) at (1.2,2.2);
\draw (O) circle (2.2);
\fill (O) circle (1.5pt);
\node[below] at (O) {$O$};
\draw (L) -- (R);
\node[above] at (T) {$T$};
\coordinate (A) at (2.167,-0.382);
\draw (T) -- (A);
\coordinate (B) at (-2.067,-0.752);
\draw (T) -- (B);
\draw (A) -- (B);
\node[left] at (B) {$B$};
\node[right] at (A) {$A$};
\pic[draw, "$50^{\circ}$", angle radius=0.6cm, angle eccentricity=2] {angle=A--T--R};
\pic[draw, "$x$", angle radius=0.5cm, angle eccentricity=2] {angle=A--B--T};
