\draw (A) -- (B);
\draw (Lc) -- (Rc);
\draw (A) -- (C) -- (B);
\node[left] at (A) {$A$};
\node[right] at (B) {$B$};
\node[above left] at (C) {$C$};
\pic[draw, "$55^{\circ}$", angle radius=0.6cm, angle eccentricity=2] {angle=B--C--Rc};
\end{tikzpicture}
[/tikz]
Find $\angle ABC$.

